-- GENERATED by `wfj generate` from data/gossip/gossip-45.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["450deb27cad2c76c"] = { "Dobbiamo vigilare per sradicare questa piaga!", "." },
  ["45115ca54fccedb2"] = { "Stringetevi attorno ai vostri tenenti e comandanti, soldati! Tenete a bada i selvaggi!", "." },
  ["4511ec986b75581e"] = { "Ah! Daryl, avresti dovuto vedere la tua faccia! Sei quasi saltato fuori dalla pelle!", "." },
  ["45188c2a052bcf6c"] = { "Ti prego, dimmi di più su Zaetar.", "." },
  ["4518accefc3a2fe2"] = { "Subito, signore.", "." },
  ["451b59393c68e9f4"] = { "Messaggio di debug: Thelrin è stato evocato.", "." },
  ["451e93114391235b"] = { "Per ora ti darò ciò che ti serve per concentrare i tuoi incantesimi e invocare gli spiriti dell'aria. Prendi questo totem e, quando sarai pront<o/a>, torna ad addestrarti con me.", "." },
  ["452047fe0c449e1d"] = { "Solo per i membri, pivello!", "." },
  ["452722a2722aacc4"] = { "Avere le capacità necessarie per sopravvivere all'aria aperta è fondamentale. Un avventuriero ben riposato e ben preparato ha molte più probabilità di sopravvivere a questo stile di vita.", "." },
  ["45289c55e39e21fe"] = { "Sono <pronto/pronta>, ⟦Anachronos=Anacronos⟧. Ti prego, concedimi lo Scettro delle Sabbie Mutevoli.", "." },
  ["4534fadfe674fb7e"] = { "Ti ringrazio, {name}. E anche mio fratello ti ringrazia.", "." },
  ["454270c99b799a3e"] = { "Soldato semplice Thorsen di ritorno dalla pattuglia. Niente di nuovo da riferire: là fuori è tutto piuttosto tranquillo...", "." },
  ["4548b9009f849540"] = { "Sì, ti mostrerò qualcosa. Vediamo come te la cavi, magari mi sorprenderai!", "." },
  ["4549d64f04b60996"] = { "Grazie, Keldric. A dopo.", "." },
  ["454c03f8388404bf"] = { "Basta per oggi, uomini!", "." },
  ["454ce2f021a4bb69"] = { "Il mio compito è svolto!", "." },
  ["454d1a618f0ff202"] = { "Vorrei addestrarmi in Cucina.", "." },
  ["455334ff3ce9e62b"] = { "Oh, chiudi il becco.", "." },
  ["45547e1124c5dc59"] = { "%s sussurra a {name} il segreto per aprire il suo forziere.", "." },
  ["455b945896d6dbca"] = { "{name}, cosa aspetti? Trova il Primo Maresciallo nel ⟦Field of Strife=Pian della Discordia⟧ e consegnagli gli ordini d'assalto. Appena li riceverà, lui e le sue truppe caricheranno l'⟦Horde=Orda⟧ senza fare prigionieri!", "." },
  ["45619570199247b9"] = { "Che storia! Quindi è entrata nell'⟦Hive'Regal=Alveare Regal⟧ e quella è stata l'ultima volta che l'hai vista?", "." },
  ["456e3b44d6eabbc8"] = { "In cambio di un ⟦Sulfuron Ingot=Lingotto di Sulfuron⟧ ho l'autorizzazione a concederti una copia dei progetti per forgiare un Martello di Sulfuron.\n\nOra, chi è avventuroso come te starà probabilmente pensando: \"A che mi servirebbe mai un martello così, quando quello che ho già è di gran lunga superiore?\"\n\nBe', lascia che ti dica una cosa, <bello/bella>: non c'è niente di più superiore di ciò che può diventare il Martello di Sulfuron!", "." },
  ["457154469262957a"] = { "Mmh... posso collegare questo filo qui e così alimento l'ingranaggio fizzletan, ma poi all'idroflangia servirà un'altra fonte di energia... Forse posso... Oh, ciao! Ehi, vuoi aiutarmi a provare una nuova invenzione?", "." },
  ["4574447295f03db0"] = { "Bah, i ladri non hanno fatto altro che rendere più difficile il nostro lavoro qui a ⟦Stormwind=Roccavento⟧. Vorrei poter trascinare sia Osborne sia Mathias fuori dalla Città Vecchia e dritti alle ⟦Stockade=Segrete di Roccavento⟧.", "." },
  ["457e66ce58fa3c51"] = { "Trova il maestro delle viverne in cima alla Sky Tower, nella ⟦Valley of Strength=Valle della Forza⟧. Doras farà in modo che tu trovi la strada per la battaglia che cerchi.", "." },
  ["4590b956e921e27c"] = { "Stai solo rimandando l'inevitabile, {race}. Arrenditi. Lei libererà la tua anima smarrita.", "." },
  ["45980b4f981becdd"] = { "%s abbassa la voce fino a un sussurro.", "." },
  ["459d0cbea3ece8f0"] = { "Il mio compito è fornire ai paladini di ⟦Bandarion Keep=Forte Bandarion⟧ armi e armature adeguate. Non è granché, ma è un lavoro onesto.\r\n\nHo anche qualcosa in vendita, se ti serve dell'equipaggiamento.", "." },
  ["45a1160aeb73debe"] = { "Amichevole", "." },
  ["45a22b426024c228"] = { "Dobbiamo andare a riunirci con gli altri Discepoli. C'è molto lavoro da fare prima che possa tentare di nuovo di risanare le ⟦Barrens=Savane⟧. Addio, anime coraggiose!", "." },
  ["45a25ef248c7ca7c"] = { "Sei sicur<o/a> che sia la strada giusta? Forse dovremmo andare da questa parte...", "." },
  ["45a44d03ecea37a4"] = { "L'⟦Horde=Orda⟧ ha preso la ⟦Irondeep Mine=Miniera di Ferrofondo⟧!", "." },
  ["45aa77ff9ecb29eb"] = { "Il ⟦Icewing Bunker=Fortilizio di Algidala⟧ controlla il passo tra il territorio dell'⟦Alliance=Alleanza⟧ e il ⟦Field of Strife=Pian della Discordia⟧.\n\nÈ in mano all'⟦Horde=Orda⟧.", "." },
  ["45b3a62762da2731"] = { "Non combattere con armi e armature rotte! Qui riparazioni esperte di armature e armi, mentre aspetti!", "." },
  ["45b8d4b5ec6b4e49"] = { "Provo vergogna, vecchio amico. Non so più cosa faccio. Non sei tu che oseresti disonorare gli eroi della leggenda: sono io. Io e il resto di questi politici corrotti. Riempiono le nostre vite di promesse vuote e menzogne senza fine.", "." },
  ["45bb526d89ce5e43"] = { "Combattete! Combattete per le vostre famiglie!", "." },
  ["45e346b817fc37b4"] = { "Ah! Tranne i loro capi, il satiro Bazzalan e lo stregone Jergosh, sì, tutti quanti. È per questo che mando continuamente i fedeli di Thrall contro di loro. Così Thrall ha l'impressione che io stia estirpando il male dalle viscere della sua grande città. In realtà la vittoria è duplice: uccido i fedeli di Thrall e metto alla prova la forza di quelli della ⟦Searing Blade=Lama Rovente⟧, per vedere se sono davvero degni di unirsi a me.", "." },
  ["45e3990493eabc9f"] = { "In attesa di ordini!", "." },
  ["45e537292af1f836"] = { "Ogni articolo che vendo me lo sono procurato personalmente. Hai la mia garanzia personale di autenticità.", "." },
  ["45ea7653376cdbf0"] = { "A dis punto tu sai quanto me, mon. Forse tu vai a trovare Magar a Orgrimmar. Lui non essere il sarto più allegro in giro, ma ti aiuta lo stesso.", "." },
  ["45f90ffaf7fadf5f"] = { "Dov'è l'anziano Corno Tonante?", "." },
  ["45fe0e32dc25b569"] = { "Prendi il tuo regalo dal mucchio.", "." },
})
